  if (cm) { civic = { num: parseInt(cm[1], 10), suffix: (cm[2] || '').toUpperCase(), raw: cm[1] + (cm[2] || '').toUpperCase() }; rest = cm[3]; }
  return { unit, civic, streetRaw: rest.split(',')[0].trim() };
