  const prompt = 'FACTS (the only data you may use):\n' + factsText + '\n\nCONTACT: ' + (who ? ((who.name || 'a client') + ' <' + who.email + '>') : 'not yet in the CRM') + '\n\nTHREAD (oldest first):\n' + threadText + '\n\nWrite the JSON draft now.';
