  if (am) return pageDict.replace(am[0], '/Contents [' + am[1] + ' ' + newRefNum + ' 0 R]');
  if (pageDict.indexOf('/Contents') !== -1) return null; // stream-form contents — bail
  return pageDict.replace(/>>\s*$/, ' /Contents ' + newRefNum + ' 0 R >>');
