    const tok = await gcalAccessToken(sa);
    if (!tok) { await env.LEADS.put('gcalerr', JSON.stringify({ at: new Date().toISOString(), step: 'token', error: gTokErr })); await gcalStamp(env, false, null, gTokErr || 'token'); return; }
