      const objPathB = NEEDS_KEY_B[sb.op] ? SITE_SPILL_PREFIX + famB + '/' + (await sha256hex(keyB)) + '.json' : null;
      const manPathB = SITE_SPILL_PREFIX + '_manifest/' + famB + '.json';
